BEGIN;

CREATE TABLE IF NOT EXISTS "permission" (
  "id" SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" VARCHAR(100) UNIQUE NOT NULL
);

CREATE TABLE IF NOT EXISTS "role_permission" (
  "role_id" SMALLINT NOT NULL REFERENCES "role" ("id") ON DELETE CASCADE,
  "permission_id" SMALLINT NOT NULL REFERENCES "permission" ("id") ON DELETE CASCADE,
  PRIMARY KEY ("role_id", "permission_id")
);

CREATE INDEX IF NOT EXISTS "idx_role_permission_permission"
  ON "role_permission" ("permission_id");

INSERT INTO "role" ("name") VALUES ('USER')
ON CONFLICT ("name") DO NOTHING;

INSERT INTO "permission" ("name") VALUES
  ('customers.read'),
  ('customers.create'),
  ('customers.update'),
  ('customers.delete'),
  ('customers.call'),
  ('requisitions.read'),
  ('requisitions.create'),
  ('sales-reports.read'),
  ('goods-requests.read'),
  ('goods-requests.create'),
  ('goods-requests.approve'),
  ('advertising-materials.read'),
  ('advertising-materials.create'),
  ('employees.read'),
  ('finance.read'),
  ('production.read')
ON CONFLICT ("name") DO NOTHING;

DELETE FROM "role_permission" role_permission
USING "role" role, "permission" permission
WHERE role_permission.role_id = role.id
  AND role_permission.permission_id = permission.id
  AND (
    (role.name = 'CEO'
      AND permission.name IN (
        'customers.create',
        'customers.update',
        'customers.delete',
        'requisitions.create',
        'goods-requests.create',
        'goods-requests.approve',
        'advertising-materials.create'
      ))
    OR
    (role.name = 'MANAGER'
      AND permission.name IN ('customers.create', 'customers.update', 'customers.delete'))
    OR
    (role.name = 'MANAGER'
      AND permission.name IN (
        'requisitions.create',
        'goods-requests.create',
        'goods-requests.approve',
        'advertising-materials.create'
      ))
  );

INSERT INTO "role_permission" ("role_id", "permission_id")
SELECT role.id, permission.id
FROM "role" role
JOIN "permission" permission ON permission.name IN (
  'customers.read', 'customers.call',
  'requisitions.read', 'sales-reports.read',
  'goods-requests.read', 'advertising-materials.read',
  'employees.read', 'finance.read', 'production.read'
)
WHERE role.name = 'CEO'
ON CONFLICT DO NOTHING;

INSERT INTO "role_permission" ("role_id", "permission_id")
SELECT role.id, permission.id
FROM "role" role
JOIN "permission" permission ON permission.name IN (
  'customers.read', 'customers.call',
  'requisitions.read', 'sales-reports.read',
  'goods-requests.read', 'advertising-materials.read',
  'employees.read', 'production.read'
)
WHERE role.name = 'MANAGER'
ON CONFLICT DO NOTHING;

INSERT INTO "role_permission" ("role_id", "permission_id")
SELECT role.id, permission.id
FROM "role" role
JOIN "permission" permission ON permission.name IN (
  'customers.read', 'customers.create', 'customers.update', 'customers.delete', 'customers.call',
  'requisitions.read', 'requisitions.create', 'sales-reports.read',
  'goods-requests.read', 'goods-requests.create',
  'advertising-materials.read', 'advertising-materials.create'
)
WHERE role.name = 'SALES_REP'
ON CONFLICT DO NOTHING;

COMMIT;
